import { InventoryService } from '../api/inventoryService';
import { AuthService } from '../api/authService';

/**
 * Automated Test Suite for Room Check-In Audit & Property Inspection [INVENTORY-01 - INVENTORY-05].
 * Verifies joint room property check-in inspections (mattress, fan, sockets, locks, lights, windows condition),
 * student/porter digital touchscreen signatures, auto-generated check-in defect reports,
 * cryptographic SHA-256 digital certificate pass generation, physical room key handover,
 * resident status activation (ACTIVE_RESIDENT), and checkout audits.
 *
 * Includes plain-language English comments for non-technical stakeholders and hostel porters.
 */
describe('InventoryService - Room Check-In Audit & Property Inspection [INVENTORY-01 - INVENTORY-05]', () => {
  const testRoomId = `rm_jaja_a_101_${Date.now()}`;
  const testStudentId = `usr_student_inv_${Date.now()}`;
  const testPorterId = `usr_porter_inv_${Date.now()}`;

  beforeAll(async () => {
    await InventoryService.initializeSchema();
    const client = AuthService.getDbClient();

    // Register test student and porter in database
    await client.execute({
      sql: `INSERT INTO users (id, matric_or_staff_no, full_name, email, password_hash, phone_number, role, gender, is_active)
            VALUES (?, ?, 'Inventory Test Student', ?, 'hashed_pass_123', '08011112222', 'STUDENT', 'MALE', 1)`,
      args: [testStudentId, `MAT_INV_${Date.now()}`, `inv_student_${Date.now()}@unilag.edu.ng`]
    });

    await client.execute({
      sql: `INSERT INTO student_profiles (user_id, faculty, department, level, campus, priority_category, fees_paid, clearance_status, residency_status)
            VALUES (?, 'Engineering', 'Systems Engineering', 100, 'MAIN_CAMPUS', 'FRESHER', 1, 'APPROVED', 'PENDING_CHECKIN')`,
      args: [testStudentId]
    });

    await client.execute({
      sql: `INSERT INTO users (id, matric_or_staff_no, full_name, email, password_hash, phone_number, role, gender, is_active)
            VALUES (?, ?, 'Inventory Test Porter', ?, 'hashed_pass_123', '08033334444', 'PORTER', 'MALE', 1)`,
      args: [testPorterId, `STF_INV_${Date.now()}`, `inv_porter_${Date.now()}@unilag.edu.ng`]
    });
  });

  test('should initialize schema and query empty initial audits', async () => {
    const audits = await InventoryService.getAuditsByStudent(testStudentId);
    expect(audits).toBeDefined();
    expect(audits).toHaveLength(0);
  });

  test('should record a room check-in inventory audit with property conditions and signatures [INVENTORY-01]', async () => {
    const audit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'FAIR',
      locksCondition: 'GOOD',
      studentSignatureUrl: 'https://unilagstay.edu.ng/sigs/student_sig.png',
      porterSignatureUrl: 'https://unilagstay.edu.ng/sigs/porter_sig.png',
      notes: 'Fan regulator knob slightly loose on check-in inspection.'
    });

    expect(audit).toBeDefined();
    expect(audit.id).toContain('audit_');
    expect(audit.roomId).toBe(testRoomId);
    expect(audit.studentId).toBe(testStudentId);
    expect(audit.porterId).toBe(testPorterId);
    expect(audit.mattressCondition).toBe('GOOD');
    expect(audit.socketsCondition).toBe('FAIR');
    expect(audit.notes).toContain('Fan regulator');
  });

  test('should verify joint student and porter touchscreen digital signatures [INVENTORY-02 / UAT-0027]', async () => {
    const audit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      studentSignatureUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
      porterSignatureUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=='
    });

    expect(audit.hasStudentSignature).toBe(true);
    expect(audit.hasPorterSignature).toBe(true);
    expect(audit.studentSignatureUrl).toContain('data:image/png');
    expect(audit.porterSignatureUrl).toContain('data:image/png');
  });

  test('should auto-generate maintenance defect report when check-in item is marked POOR [INVENTORY-03 / UAT-0028]', async () => {
    const audit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'POOR',
      fanCondition: 'GOOD',
      socketsCondition: 'POOR',
      locksCondition: 'GOOD',
      notes: 'Broken spring in mattress and socket faceplate damaged.'
    });

    expect(audit.autoGeneratedDefects).toBeDefined();
    expect(audit.autoGeneratedDefects?.length).toBe(2);

    // Verify defect ticket was inserted into maintenance_tickets in database
    const client = AuthService.getDbClient();
    const ticketRes = await client.execute({
      sql: `SELECT id, category, description, status FROM maintenance_tickets WHERE student_id = ? AND room_number = ?`,
      args: [testStudentId, testRoomId]
    });

    expect(ticketRes.rows.length).toBeGreaterThanOrEqual(2);
    expect(String(ticketRes.rows[0].status)).toBe('OPEN');
  });

  test('should record a room check-in inventory audit with all 6 fixtures including lights and windows [INVENTORY-04 / UAT-0029]', async () => {
    const audit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'FAIR',
      windowsCondition: 'GOOD',
      keyIssued: true,
      keyTagNumber: 'KEY-JAJA-101-A',
      studentSignatureUrl: 'sig_student_verified',
      porterSignatureUrl: 'sig_porter_verified',
      notes: 'All items verified on check-in. One fluorescent tube dim.'
    });

    expect(audit).toBeDefined();
    expect(audit.lightsCondition).toBe('FAIR');
    expect(audit.windowsCondition).toBe('GOOD');
    expect(audit.keyIssued).toBe(true);
    expect(audit.keyTagNumber).toBe('KEY-JAJA-101-A');
    expect(audit.keyIssuedAt).toBeDefined();
    expect(audit.certificateHash).toBeDefined();
    expect(audit.certificateHash!).toMatch(/^AUDIT-CERT-[A-Z0-9]{16}$/);
  });

  test('should auto-generate maintenance defect tickets for poor lighting and damaged windows [INVENTORY-04 / UAT-0029]', async () => {
    const auditWithLightingDefect = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'POOR',
      windowsCondition: 'POOR',
      notes: 'Fluorescent lamp broken and window louver pane missing.'
    });

    expect(auditWithLightingDefect.autoGeneratedDefects).toBeDefined();
    expect(auditWithLightingDefect.autoGeneratedDefects?.length).toBe(2);

    const client = AuthService.getDbClient();
    const lightTicket = await client.execute({
      sql: `SELECT id, category, description FROM maintenance_tickets WHERE id IN (?, ?)`,
      args: [auditWithLightingDefect.autoGeneratedDefects![0], auditWithLightingDefect.autoGeneratedDefects![1]]
    });

    expect(lightTicket.rows.length).toBe(2);
    const categories = lightTicket.rows.map(r => String(r.category));
    expect(categories).toContain('ELECTRICAL');
    expect(categories).toContain('CARPENTRY');
  });

  test('should record official room key handover issuance and tag tracking [INVENTORY-04 / UAT-0029]', async () => {
    const auditWithoutKey = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'GOOD',
      windowsCondition: 'GOOD',
      keyIssued: false
    });

    expect(auditWithoutKey.keyIssued).toBe(false);
    expect(auditWithoutKey.keyTagNumber).toBeUndefined();

    const updated = await InventoryService.issueRoomKey(auditWithoutKey.id, 'KEY-JAJA-101-B');

    expect(updated.id).toBe(auditWithoutKey.id);
    expect(updated.keyIssued).toBe(true);
    expect(updated.keyTagNumber).toBe('KEY-JAJA-101-B');
    expect(updated.keyIssuedAt).toBeDefined();

    const fetched = await InventoryService.getAuditById(auditWithoutKey.id);
    expect(fetched.keyIssued).toBe(true);
    expect(fetched.keyTagNumber).toBe('KEY-JAJA-101-B');
  });

  test('should verify audit certificate authenticity by cryptographic hash [INVENTORY-04 / UAT-0029]', async () => {
    const audit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'GOOD',
      windowsCondition: 'GOOD',
      keyIssued: true,
      keyTagNumber: 'KEY-JAJA-101-C'
    });

    const certHash = audit.certificateHash!;
    const verified = await InventoryService.verifyAuditCertificate(certHash);

    expect(verified).toBeDefined();
    expect(verified.id).toBe(audit.id);
    expect(verified.roomId).toBe(testRoomId);
    expect(verified.studentId).toBe(testStudentId);
    expect(verified.certificateHash).toBe(certHash);
    expect(verified.keyIssued).toBe(true);
  });

  test('should reject certificate verification for non-existent hash [INVENTORY-04]', async () => {
    await expect(
      InventoryService.verifyAuditCertificate('AUDIT-CERT-NONEXISTENT')
    ).rejects.toThrow('Room inventory audit certificate not found or invalid');
  });

  test('should reject key handover for non-existent audit ID or empty key tag [INVENTORY-04]', async () => {
    await expect(
      InventoryService.issueRoomKey('non_existent_audit_id', 'KEY-JAJA-999')
    ).rejects.toThrow('Room inventory audit record not found');

    await expect(
      InventoryService.issueRoomKey(testRoomId, '   ')
    ).rejects.toThrow('Key tag number or label identifier is required');
  });

  test('should complete check-in and transition student to ACTIVE_RESIDENT [INVENTORY-05 / UAT-0030]', async () => {
    // 1. Create audit with complete signatures and key issuance
    const completeAudit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'GOOD',
      windowsCondition: 'GOOD',
      keyIssued: true,
      keyTagNumber: 'KEY-JAJA-101-RES',
      studentSignatureUrl: 'sig_touch_student',
      porterSignatureUrl: 'sig_touch_porter'
    });

    // 2. Complete check-in and activate residency
    const activation = await InventoryService.completeCheckInAndActivateResident(completeAudit.id);

    expect(activation).toBeDefined();
    expect(activation.studentId).toBe(testStudentId);
    expect(activation.residencyStatus).toBe('ACTIVE_RESIDENT');
    expect(activation.keyIssued).toBe(true);
    expect(activation.keyTagNumber).toBe('KEY-JAJA-101-RES');

    // 3. Verify in Turso DB student_profiles table
    const client = AuthService.getDbClient();
    const profile = await client.execute({
      sql: `SELECT residency_status FROM student_profiles WHERE user_id = ?`,
      args: [testStudentId]
    });
    expect(String(profile.rows[0].residency_status)).toBe('ACTIVE_RESIDENT');
  });

  test('should reject residency activation if signatures or key issuance are missing [INVENTORY-05]', async () => {
    // Audit without signatures
    const incompleteAudit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      keyIssued: false
    });

    await expect(
      InventoryService.completeCheckInAndActivateResident(incompleteAudit.id)
    ).rejects.toThrow('Check-in cannot be completed without student touchscreen signature');
  });

  test('should record end-of-session move-out / checkout audit [INVENTORY-05 / UAT-0030]', async () => {
    const checkoutAudit = await InventoryService.recordAudit({
      roomId: testRoomId,
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'FAIR',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD',
      lightsCondition: 'GOOD',
      windowsCondition: 'GOOD',
      auditType: 'CHECK_OUT',
      keyIssued: true,
      keyTagNumber: 'KEY-JAJA-101-RES',
      studentSignatureUrl: 'sig_student_checkout',
      porterSignatureUrl: 'sig_porter_checkout',
      notes: 'End of session room clearance completed. Room left in clean state.'
    });

    expect(checkoutAudit).toBeDefined();
    expect(checkoutAudit.auditType).toBe('CHECK_OUT');
    expect(checkoutAudit.certificateHash).toContain('AUDIT-CERT-');
  });

  test('should fetch recorded room audits by student ID', async () => {
    const studentAudits = await InventoryService.getAuditsByStudent(testStudentId);
    expect(studentAudits.length).toBeGreaterThanOrEqual(1);
    expect(studentAudits[0].roomId).toBe(testRoomId);
    expect(studentAudits[0].studentName).toBe('Inventory Test Student');
    expect(studentAudits[0].porterName).toBe('Inventory Test Porter');
  });

  test('should fetch recorded room audits by room ID [UAT-0026]', async () => {
    const roomAudits = await InventoryService.getAuditsByRoom(testRoomId);
    expect(roomAudits.length).toBeGreaterThanOrEqual(1);
    expect(roomAudits[0].studentId).toBe(testStudentId);
  });

  test('should fail recording audit if required parameters are missing', async () => {
    await expect(InventoryService.recordAudit({
      roomId: '   ',
      studentId: testStudentId,
      porterId: testPorterId,
      mattressCondition: 'GOOD',
      fanCondition: 'GOOD',
      socketsCondition: 'GOOD',
      locksCondition: 'GOOD'
    })).rejects.toThrow('Valid room ID is required');
  });
});
